import Image from 'next/image'
import Link from 'next/link'
import { cn } from 'cn'

type LogoProps = {
  /** "light" = ink wordmark on paper; "on-ink" = paper wordmark on a dark panel */
  tone?: 'light' | 'on-ink'
  href?: string
  className?: string
}

/** Jaden's head mark + wordmark. The mark is generated by `npm run brand:icons`. */
export function Logo({ tone = 'light', href = '/', className }: LogoProps) {
  return (
    <Link
      href={href}
      className={cn('flex items-center gap-2 px-1', className)}
      aria-label="JADEN home"
    >
      <Image
        src="/brand/jaden-mark.svg"
        alt=""
        width={34}
        height={34}
        unoptimized
        className="size-[34px] shrink-0"
      />
      <span
        className={cn(
          'font-serif text-[19px] leading-none font-semibold',
          tone === 'light' ? 'text-neutral-900' : 'text-on-ink',
        )}
      >
        JADEN
      </span>
    </Link>
  )
}
